'@
$codigoB64 = $codigoB64 -replace "\s", ""

$tmpB64 = Join-Path $env:TEMP "chronos_inst_v6.b64"
$tmpPy = Join-Path $env:TEMP "chronos_inst_v6.py"
Set-Content -Path $tmpB64 -Value $codigoB64 -NoNewline -Encoding ascii

$decodeScript = @'
import base64, zlib, sys
with open(sys.argv[1], "r", encoding="ascii") as f:
    dados = f.read()
codigo = zlib.decompress(base64.b64decode(dados))
exec(compile(codigo, "instalador-chronos", "exec"))
'@
Set-Content -Path $tmpPy -Value $decodeScript -Encoding ascii

python $tmpPy $tmpB64
if ($LASTEXITCODE -ne 0) {
    Write-Host "ERRO ao aplicar as atualizacoes. Nada foi publicado. Veja a mensagem acima." -ForegroundColor Red
    Remove-Item $tmpB64, $tmpPy -ErrorAction SilentlyContinue
    exit 1
}
Remove-Item $tmpB64, $tmpPy -ErrorAction SilentlyContinue

Write-Host "3) Instalando dependencias e compilando (npm run build)..." -ForegroundColor Cyan
npm install --silent
if ($LASTEXITCODE -ne 0) { Write-Host "ERRO no npm install." -ForegroundColor Red; exit 1 }
npm run build
if ($LASTEXITCODE -ne 0) { Write-Host "ERRO no build. As mudancas NAO foram publicadas. Corrija o erro acima e rode de novo." -ForegroundColor Red; exit 1 }

Write-Host "4) Build ok! Enviando para o GitHub (a Vercel publica sozinha)..." -ForegroundColor Cyan
git add -A
git commit -m "Ferramentas de Pratica organizadas por bimestre/ano, com botao de avancar no admin" -q
if ($LASTEXITCODE -ne 0) { Write-Host "ERRO ao commitar." -ForegroundColor Red; exit 1 }
git push
if ($LASTEXITCODE -ne 0) { Write-Host "ERRO ao enviar (git push). O commit foi feito localmente; rode 'git push' de novo." -ForegroundColor Red; exit 1 }

Write-Host ""
Write-Host "PRONTO! Build ok e enviado. A Vercel vai publicar em 1-2 minutos." -ForegroundColor Green
Write-Host "Teste em alguns minutos: 1) em /pratica, as ferramentas continuam aparecendo normalmente (agora dentro do bimestre atual); 2) no admin (/admin/ferramentas), aparece o botao 'Avancar bimestre' ao lado de 'Nova Ferramenta'; 3) ao clicar nele e confirmar, a lista fica vazia (comecando um bimestre novo) e o bimestre anterior aparece na secao 'Bimestres anteriores' (so consulta) mais embaixo." -ForegroundColor Green
